            annotation { "Name" : "Insert hole diameter (M3 insert OD ~4.8)" }
            isLength(definition.insert_d, { (millimeter) : [2, 4.2, 8] } as LengthBoundSpec);
            annotation { "Name" : "Insert hole depth" }
