            annotation { "Name" : "Breadboard width Y" }
            isLength(definition.bb_wid, { (millimeter) : [20, 55, 200] } as LengthBoundSpec);
            annotation { "Name" : "Clearance around the breadboard" }
            isLength(definition.bb_gap, { (millimeter) : [0, 2, 20] } as LengthBoundSpec);
            annotation { "Name" : "Interior height, floor to rim" }
            isLength(definition.in_h, { (millimeter) : [10, 40, 150] } as LengthBoundSpec);
            annotation { "Name" : "Light wall thickness (optics vs bay)" }
            isLength(definition.part_t, { (millimeter) : [0.8, 1.6, 10] } as LengthBoundSpec);
            annotation { "Name" : "Wire notch width (top of light wall)" }
            isLength(definition.wire_w, { (millimeter) : [1, 24, 100] } as LengthBoundSpec);
            annotation { "Name" : "Wire notch depth" }
            isLength(definition.wire_h, { (millimeter) : [1, 10, 50] } as LengthBoundSpec);
        }
        annotation { "Group Name" : "Sample vial (SKS 20 mL, measured)", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Vial body diameter" }
            isLength(definition.vial_d, { (millimeter) : [5, 27.4, 60] } as LengthBoundSpec);
            annotation { "Name" : "Vial height with cap" }
            isLength(definition.vial_h, { (millimeter) : [20, 60, 150] } as LengthBoundSpec);
            annotation { "Name" : "Vial cap diameter" }
            isLength(definition.vcap_d, { (millimeter) : [5, 24.7, 60] } as LengthBoundSpec);
            annotation { "Name" : "Cap height gripped by the sleeve" }
            isLength(definition.vcap_h, { (millimeter) : [2, 10, 40] } as LengthBoundSpec);
            annotation { "Name" : "Vial-to-bore clearance per side" }
            isLength(definition.vial_fit, { (millimeter) : [0, 0.4, 3] } as LengthBoundSpec);
            annotation { "Name" : "Vial bottom above the floor" }
            isLength(definition.vial_z, { (millimeter) : [0, 0, 30] } as LengthBoundSpec);
            annotation { "Name" : "Gap between front wall and optics block" }
